"""Training data for a trained-policy solver, generated by backward scrambles.

The trained-policy class of solver (arXiv 2408.15332, AC-Solver) needs
supervision this campaign has never had.  The 424 certified paths are the only
labelled data the organisers publish and they are Miller-Schupp, not the random
draw the pool is made of.  The free alternative is the one that makes learned
solvers work on Rubik's cube: scramble backwards from the solved state and the
label comes for free, because the move that undoes the last scramble step is by
construction a correct move toward the target.

Two labels per visited state:
  move  - INV of the scramble move that produced it, the action a policy should
          take to move one step closer to (x, y)
  depth - the number of scramble moves applied, an UPPER BOUND on the true
          distance to (x, y), which is what a value head can regress

The scramble is length-capped so the states it produces stay inside the pool's
own regime (every pool presentation totals at most 40).  Without the cap a
random AC walk runs away to relators of several hundred letters within twenty
moves and the data never resembles a challenge.

Usage (from the repo root):
  python runs/pool/policy_data.py --n 200000 --max-depth 48 --cap 44 \
      --out runs/pool/policy/scramble.npz
"""
import argparse
import os
import pathlib
import sys
import time

import numpy as np
from numba import njit

REPO = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))
sys.path.insert(0, str(REPO / "runs" / "pool"))
from jit_engine import MAXLEN, _apply  # noqa: E402

INV = np.array([0, 1, 3, 2, 5, 4, 7, 6, 9, 8, 11, 10, 13, 12], dtype=np.int8)

# Tokens are the letters -2,-1,1,2 plus a pad, shifted into 0..4.
ENC = 48          # positions kept per relator
NTOK = 5


@njit(cache=False)
def gen_scrambles(n_walks, max_depth, cap, seed, out_w0, out_l0, out_w1,
                  out_l1, out_move, out_depth):
    """Random backward walks from (x, y), writing one row per visited state.

    A move is rejected and redrawn if it would push total relator length past
    the cap or leave a relator empty; an empty relator is a degenerate state
    the forward search never has to handle.  Returns the number of rows."""
    np.random.seed(seed)
    s0 = np.zeros(MAXLEN, dtype=np.int8)
    s1 = np.zeros(MAXLEN, dtype=np.int8)
    o0 = np.zeros(MAXLEN, dtype=np.int8)
    o1 = np.zeros(MAXLEN, dtype=np.int8)
    buf = np.zeros(MAXLEN, dtype=np.int8)
    tmp = np.zeros(MAXLEN + 2, dtype=np.int8)
    rows = 0
    for w in range(n_walks):
        s0[0] = 1
        l0 = 1
        s1[0] = 2
        l1 = 1
        depth = 0
        target = 1 + np.random.randint(max_depth)
        tries = 0
        while depth < target and rows < out_depth.shape[0]:
            mid = np.random.randint(14)
            na, nb = _apply(mid, s0, l0, s1, l1, o0, o1, buf, tmp)
            if na < 1 or nb < 1 or na + nb > cap or na >= MAXLEN or nb >= MAXLEN:
                tries += 1
                if tries > 40:
                    break
                continue
            tries = 0
            for i in range(na):
                s0[i] = o0[i]
            for i in range(nb):
                s1[i] = o1[i]
            l0 = na
            l1 = nb
            depth += 1
            if l0 == 1 and l1 == 1 and s0[0] == 1 and s1[0] == 2:
                # the walk wandered back onto the target; the suffix is noise
                break
            for i in range(MAXLEN):
                out_w0[rows, i] = s0[i] if i < l0 else 0
                out_w1[rows, i] = s1[i] if i < l1 else 0
            out_l0[rows] = l0
            out_l1[rows] = l1
            out_move[rows] = INV[mid]
            out_depth[rows] = depth
            rows += 1
    return rows


def encode(w0, l0, w1, l1):
    """Rows of int8 letters to the network's token matrix, shape (n, 2*ENC)."""
    n = w0.shape[0]
    x = np.zeros((n, 2 * ENC), dtype=np.int8)
    for j, (w, l) in enumerate(((w0, l0), (w1, l1))):
        keep = min(ENC, w.shape[1])
        blk = w[:, :keep].astype(np.int16)
        # -2,-1,0,1,2 -> 0..4, with 0 meaning pad
        blk = blk + 2
        x[:, j * ENC:j * ENC + keep] = blk.astype(np.int8)
    return x


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--walks", type=int, default=120_000)
    ap.add_argument("--max-depth", type=int, default=48)
    ap.add_argument("--cap", type=int, default=44)
    ap.add_argument("--rows", type=int, default=3_000_000)
    ap.add_argument("--seed", type=int, default=12345)
    ap.add_argument("--out", default="runs/pool/policy/scramble.npz")
    args = ap.parse_args()

    cap = min(args.cap, MAXLEN - 1)
    n = args.rows
    w0 = np.zeros((n, MAXLEN), dtype=np.int8)
    w1 = np.zeros((n, MAXLEN), dtype=np.int8)
    l0 = np.zeros(n, dtype=np.int16)
    l1 = np.zeros(n, dtype=np.int16)
    mv = np.zeros(n, dtype=np.int8)
    dp = np.zeros(n, dtype=np.int16)

    gen_scrambles(4, 6, cap, 1, w0, l0, w1, l1, mv, dp)   # compile
    t0 = time.time()
    rows = gen_scrambles(args.walks, args.max_depth, cap, args.seed,
                         w0, l0, w1, l1, mv, dp)
    el = time.time() - t0
    print(f"{rows:,} rows from {args.walks:,} walks in {el:.1f}s "
          f"({rows / max(el, 1e-9):,.0f} rows/s)", flush=True)

    x = encode(w0[:rows], l0[:rows], w1[:rows], l1[:rows])
    tot = (l0[:rows] + l1[:rows]).astype(np.int16)
    out = REPO / args.out
    out.parent.mkdir(parents=True, exist_ok=True)
    np.savez_compressed(out, x=x, move=mv[:rows], depth=dp[:rows], total=tot)
    print(f"total relator length: mean {tot.mean():.1f} max {tot.max()} "
          f"| depth: mean {dp[:rows].mean():.1f} max {dp[:rows].max()}",
          flush=True)
    print(f"wrote {out}", flush=True)
    os._exit(0)


if __name__ == "__main__":
    main()
